create table if not exists public.merchant_risk (user_id uuid primary key references auth.users(id) on delete cascade, risk_level text not null default 'unreviewed' check (risk_level in ('unreviewed','low','medium','high','blocked')), risk_score numeric, review_status text not null default 'pending' check (review_status in ('pending','in_review','approved','rejected')), reviewed_at timestamptz, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.verification_status (user_id uuid primary key references auth.users(id) on delete cascade, status text not null default 'unverified' check (status in ('unverified','pending','verified','rejected','expired')), provider text, external_reference text, verified_at timestamptz, expires_at timestamptz, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.compliance_events (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, event_type text not null, status text not null default 'recorded', external_id text, payload jsonb not null default '{}'::jsonb, occurred_at timestamptz not null default now(), created_at timestamptz not null default now());
create table if not exists public.audit_logs (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, actor_id uuid references auth.users(id) on delete set null, action text not null, resource_type text, resource_id text, request_id text, ip_hash text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table if not exists public.idempotency_keys (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, scope text not null, idempotency_key text not null, status text not null default 'processing' check (status in ('processing','completed','failed')), response_code integer, response_payload jsonb, resource_type text, resource_id text, expires_at timestamptz not null default (now() + interval '24 hours'), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id, scope, idempotency_key));
create table if not exists public.settlements (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, gateway_id text not null, external_settlement_id text, period_start timestamptz, period_end timestamptz, gross_total numeric not null default 0, fees_total numeric not null default 0, net_total numeric not null default 0, currency text not null default 'BRL', status text not null default 'pending', reconciled_at timestamptz, discrepancy_amount numeric, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.disputes (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, transaction_id uuid references public.gateway_transactions(id) on delete set null, gateway_id text, external_dispute_id text, status text not null default 'open', reason text, amount numeric, currency text default 'BRL', evidence jsonb not null default '[]'::jsonb, timeline jsonb not null default '[]'::jsonb, due_at timestamptz, submitted_at timestamptz, resolved_at timestamptz, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.merchant_risk enable row level security;
alter table public.verification_status enable row level security;
alter table public.compliance_events enable row level security;
alter table public.audit_logs enable row level security;
alter table public.idempotency_keys enable row level security;
alter table public.settlements enable row level security;
alter table public.disputes enable row level security;
create policy merchant_risk_owner_read on public.merchant_risk for select to authenticated using (user_id=auth.uid());
create policy verification_status_owner_read on public.verification_status for select to authenticated using (user_id=auth.uid());
create policy compliance_events_owner_read on public.compliance_events for select to authenticated using (user_id=auth.uid());
create policy audit_logs_owner_read on public.audit_logs for select to authenticated using (user_id=auth.uid());
create policy idempotency_keys_owner_read on public.idempotency_keys for select to authenticated using (user_id=auth.uid());
create policy settlements_owner_read on public.settlements for select to authenticated using (user_id=auth.uid());
create policy disputes_owner_read on public.disputes for select to authenticated using (user_id=auth.uid());
create unique index if not exists compliance_events_external_unique on public.compliance_events(user_id, external_id) where external_id is not null;
create index if not exists compliance_events_user_time_idx on public.compliance_events(user_id, created_at desc);
create index if not exists audit_logs_user_time_idx on public.audit_logs(user_id, created_at desc);
create index if not exists idempotency_keys_expiry_idx on public.idempotency_keys(expires_at);
create index if not exists settlements_user_gateway_time_idx on public.settlements(user_id, gateway_id, created_at desc);
create unique index if not exists settlements_gateway_external_unique on public.settlements(user_id, gateway_id, external_settlement_id) where external_settlement_id is not null;
create index if not exists disputes_user_status_due_idx on public.disputes(user_id, status, due_at);
create unique index if not exists disputes_gateway_external_unique on public.disputes(user_id, gateway_id, external_dispute_id) where external_dispute_id is not null;